#!/usr/bin/env bash
# Run Rhythm entirely against local services, for testing on a physical iPhone.
#
#   scripts/dev-local.sh          # set up local env files and start the backend
#
# - Local Supabase (Docker) for Auth + Postgres; the 6-digit sign-in codes
#   arrive in the local Mailpit inbox (printed below), not real email.
# - Backend on :8000 using local Postgres, never the hosted project.
# - mobile/.env.local points the app at this Mac's LAN address (Expo loads it
#   ahead of mobile/.env). Both generated files are git-ignored.
# Then, in another terminal: cd mobile && npx expo start
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
cd "$ROOT"

supabase status >/dev/null 2>&1 || supabase start
LAN_IP="$(ipconfig getifaddr en0 || ipconfig getifaddr en1 || echo 127.0.0.1)"
ANON_KEY="$(supabase status -o env | sed -n 's/^ANON_KEY="\{0,1\}\([^"]*\)"\{0,1\}$/\1/p')"
# Backend-only (account deletion's admin API). Exported to the backend process below, never written to the app's env.
SERVICE_ROLE_KEY="$(supabase status -o env | sed -n 's/^SERVICE_ROLE_KEY="\{0,1\}\([^"]*\)"\{0,1\}$/\1/p')"

cat > mobile/.env.local <<EOF
# Generated by scripts/dev-local.sh — local services only.
EXPO_PUBLIC_SUPABASE_URL=http://$LAN_IP:54321
EXPO_PUBLIC_SUPABASE_ANON_KEY=$ANON_KEY
EXPO_PUBLIC_API_URL=http://$LAN_IP:8000
EOF

LOCAL_ENV="backend/.env.local"
if [ ! -f "$LOCAL_ENV" ]; then
  umask 077
  cat > "$LOCAL_ENV" <<EOF
# Generated by scripts/dev-local.sh — local-only secrets (git-ignored).
TOKEN_ENCRYPTION_KEY=$(.venv/bin/python -c 'from cryptography.fernet import Fernet; print(Fernet.generate_key().decode())')
OAUTH_STATE_SECRET=$(.venv/bin/python -c 'import secrets; print(secrets.token_urlsafe(48))')
EOF
fi

set -a
# shellcheck disable=SC1090
source "$LOCAL_ENV"
set +a
export DATABASE_URL="postgresql+psycopg://postgres:postgres@127.0.0.1:54322/postgres"
export SUPABASE_URL="http://127.0.0.1:54321"
export SUPABASE_JWT_SECRET=""
export SUPABASE_SERVICE_ROLE_KEY="$SERVICE_ROLE_KEY"
# No OpenAI calls locally unless asked for: RHYTHM_LOCAL_LLM=1 scripts/dev-local.sh
if [ "${RHYTHM_LOCAL_LLM:-0}" = "1" ]; then export RECOMMENDATIONS_LLM_ENABLED=true; else export RECOMMENDATIONS_LLM_ENABLED=false; fi

.venv/bin/alembic -c backend/alembic.ini -x "url=$DATABASE_URL" upgrade head

echo
echo "Local Rhythm"
echo "  API (phone):     http://$LAN_IP:8000"
echo "  Sign-in codes:   http://127.0.0.1:54324  (Mailpit inbox)"
echo "  App env:         mobile/.env.local"
echo "  OpenAI wording:  $RECOMMENDATIONS_LLM_ENABLED (RHYTHM_LOCAL_LLM=1 to enable)"
echo
exec .venv/bin/uvicorn backend.main:app --host 0.0.0.0 --port 8000
